import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"ja/concepts/workspace.md","filePath":"ja/concepts/workspace.md","lastUpdated":1784904021000}'),n={name:"ja/concepts/workspace.md"};function p(l,a,h,o,d,c){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="workspace" tabindex="-1">Workspace <a class="header-anchor" href="#workspace" aria-label="Permalink to &quot;Workspace&quot;">​</a></h1><p>ワークスペースは、swag2mcp がすべてのデータ（設定、キャッシュされた spec、ローカル spec ファイル、保存されたレスポンス、認証スクリプト）を保存するディレクトリです。</p><h2 id="構造" tabindex="-1">構造 <a class="header-anchor" href="#構造" aria-label="Permalink to &quot;構造&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/                          # ワークスペースルート（デフォルト）</span></span>
<span class="line"><span>├── swag2mcp.yaml                     # 設定ファイル</span></span>
<span class="line"><span>├── cache/                            # キャッシュされたリモート spec ファイル</span></span>
<span class="line"><span>│   ├── a1b2c3d4e5f6...spec          # キャッシュされた spec の内容</span></span>
<span class="line"><span>│   └── a1b2c3d4e5f6...meta          # キャッシュメタデータ（JSON）</span></span>
<span class="line"><span>├── specs/                            # ローカル spec ファイル</span></span>
<span class="line"><span>│   └── my-api.yaml</span></span>
<span class="line"><span>├── responses/                        # 保存された API レスポンス（大きなレスポンス）</span></span>
<span class="line"><span>│   ├── meteo-get-forecast-abc123.json</span></span>
<span class="line"><span>│   └── response-fragment-def456.json</span></span>
<span class="line"><span>└── auth_scripts/                     # 認証スクリプト</span></span>
<span class="line"><span>    ├── meteo.sh                      # Unix シェルスクリプト</span></span>
<span class="line"><span>    └── meteo.bat                     # Windows バッチスクリプト</span></span></code></pre></div><h2 id="デフォルトパス" tabindex="-1">デフォルトパス <a class="header-anchor" href="#デフォルトパス" aria-label="Permalink to &quot;デフォルトパス&quot;">​</a></h2><ul><li><strong>Linux/macOS</strong>: <code>~/.swag2mcp/</code></li><li><strong>Windows</strong>: <code>%USERPROFILE%\\.swag2mcp\\</code></li></ul><h2 id="カスタムパス" tabindex="-1">カスタムパス <a class="header-anchor" href="#カスタムパス" aria-label="Permalink to &quot;カスタムパス&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-workspace</span></span></code></pre></div><h2 id="ディレクトリ" tabindex="-1">ディレクトリ <a class="header-anchor" href="#ディレクトリ" aria-label="Permalink to &quot;ディレクトリ&quot;">​</a></h2><h3 id="cache" tabindex="-1">cache/ <a class="header-anchor" href="#cache" aria-label="Permalink to &quot;cache/&quot;">​</a></h3><p>ダウンロードされたリモート spec ファイルを保存します。各ファイルは URL の SHA-256 ハッシュをファイル名としてキャッシュされます：</p><ul><li><code>{hash}.spec</code> — キャッシュされた spec ファイルの内容</li><li><code>{hash}.meta</code> — JSON メタデータ（ソース URL、キャッシュ時間、TTL）</li></ul><p>各キャッシュファイルには 1 時間から 48 時間の間でランダムな TTL があります。キャッシュは起動のたびに自動的にチェックされます — 有効な（期限切れでない）エントリが存在する場合、ダウンロードせずに再利用されます。</p><p><strong>コマンド:</strong></p><ul><li><code>swag2mcp update</code> — キャッシュをクリアし、すべての spec を再ダウンロード</li><li><code>swag2mcp clean</code> — キャッシュとレスポンスをクリア</li></ul><h3 id="specs" tabindex="-1">specs/ <a class="header-anchor" href="#specs" aria-label="Permalink to &quot;specs/&quot;">​</a></h3><p>collection が <code>location: specs/{name}</code> を介して指すローカル spec ファイルを保存します。ここにあるファイルはキャッシュなしで直接使用されます。</p><p>このディレクトリは以下によって作成されます：</p><ul><li><code>swag2mcp import &amp;lt;source&amp;gt; &amp;lt;name&amp;gt;</code> — リモート spec をダウンロードしてここに保存</li><li><code>swag2mcp export</code> — ここからエクスポート ZIP に spec をコピー</li><li>手動配置 — 自分で spec ファイルをコピーできます</li></ul><h3 id="responses" tabindex="-1">responses/ <a class="header-anchor" href="#responses" aria-label="Permalink to &quot;responses/&quot;">​</a></h3><p><code>max_response_size</code> 制限（デフォルト 1 MB）を超える API レスポンスを保存します。LLM がエンドポイントを呼び出し、レスポンスが大きすぎる場合、swag2mcp はここに保存し、代わりにファイル参照を返します。</p><p>命名規則：<code>{domain}-{method}-{path_with_underscores}-{6char_hex}.json</code></p><p>古いレスポンスは MCP サーバー起動後 48 時間で自動的にクリーンアップされます。</p><h3 id="auth-scripts" tabindex="-1">auth_scripts/ <a class="header-anchor" href="#auth-scripts" aria-label="Permalink to &quot;auth_scripts/&quot;">​</a></h3><p><code>script</code> 認証タイプの認証スクリプトを保存します。各スクリプトは spec のドメインにちなんで命名されます。</p><h4 id="命名規則" tabindex="-1">命名規則 <a class="header-anchor" href="#命名規則" aria-label="Permalink to &quot;命名規則&quot;">​</a></h4><table tabindex="0"><thead><tr><th>プラットフォーム</th><th>ファイル名</th><th>例</th></tr></thead><tbody><tr><td>Unix（Linux、macOS）</td><td><code>{domain}.sh</code></td><td><code>meteo.sh</code></td></tr><tr><td>Windows</td><td><code>{domain}.bat</code></td><td><code>meteo.bat</code></td></tr></tbody></table><p>ドメインに <code>/</code> または <code>\\</code> 文字を含めることはできません。</p><h4 id="スクリプトの仕組み" tabindex="-1">スクリプトの仕組み <a class="header-anchor" href="#スクリプトの仕組み" aria-label="Permalink to &quot;スクリプトの仕組み&quot;">​</a></h4><ol><li>swag2mcp は 30 秒のタイムアウトでスクリプトを実行します</li><li>スクリプトは有効な JSON を stdout に出力する必要があります</li><li>swag2mcp は JSON を解析し、API リクエストにトークンを使用します</li></ol><h4 id="期待される出力形式" tabindex="-1">期待される出力形式 <a class="header-anchor" href="#期待される出力形式" aria-label="Permalink to &quot;期待される出力形式&quot;">​</a></h4><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-token-here&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expires_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>フィールド</th><th>型</th><th>必須</th><th>説明</th></tr></thead><tbody><tr><td><code>token</code></td><td>string</td><td>✅</td><td>認証トークン</td></tr><tr><td><code>access_token</code></td><td>string</td><td>❌</td><td><code>token</code> の代替（最初にチェック）</td></tr><tr><td><code>token_type</code></td><td>string</td><td>❌</td><td>トークンタイプ（例：&quot;Bearer&quot;）</td></tr><tr><td><code>expires_in</code></td><td>number</td><td>❌</td><td>トークンの有効期間（秒）（デフォルト：3600）</td></tr></tbody></table><h4 id="実行" tabindex="-1">実行 <a class="header-anchor" href="#実行" aria-label="Permalink to &quot;実行&quot;">​</a></h4><table tabindex="0"><thead><tr><th>プラットフォーム</th><th>コマンド</th></tr></thead><tbody><tr><td>Unix</td><td><code>sh {domain}.sh</code></td></tr><tr><td>Windows</td><td><code>cmd /c {domain}.bat</code></td></tr></tbody></table><h4 id="トークンキャッシュ" tabindex="-1">トークンキャッシュ <a class="header-anchor" href="#トークンキャッシュ" aria-label="Permalink to &quot;トークンキャッシュ&quot;">​</a></h4><p>トークンは期限が切れるまでメモリ内にキャッシュされます。API 呼び出しのたびに、swag2mcp は最初にキャッシュをチェックします — スクリプトはキャッシュされたトークンが期限切れになった場合のみ実行されます。</p><h4 id="スタブの作成" tabindex="-1">スタブの作成 <a class="header-anchor" href="#スタブの作成" aria-label="Permalink to &quot;スタブの作成&quot;">​</a></h4><p><code>auth: { type: script, config: { domain: &quot;myapi&quot; } }</code> を設定すると、swag2mcp は自動的にスタブスクリプトを作成します：</p><p><strong>Unix（<code>auth_scripts/myapi.sh</code>）:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;token&quot;: &quot;your-token-here&quot;, &quot;expires_in&quot;: 3600}&#39;</span></span></code></pre></div><p><strong>Windows（<code>auth_scripts/myapi.bat</code>）:</strong></p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@echo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> off</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-token-here&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;expires_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 3600}</span></span></code></pre></div><p>プレースホルダートークンを実際の認証ロジックに置き換えてください。</p><h4 id="孤立スクリプトのクリーンアップ" tabindex="-1">孤立スクリプトのクリーンアップ <a class="header-anchor" href="#孤立スクリプトのクリーンアップ" aria-label="Permalink to &quot;孤立スクリプトのクリーンアップ&quot;">​</a></h4><p>spec を削除すると、その認証スクリプトは孤立します。swag2mcp は以下で自動的に孤立スクリプトを削除します：</p><ul><li><code>swag2mcp update</code></li><li><code>swag2mcp clean</code></li></ul><h2 id="コマンド" tabindex="-1">コマンド <a class="header-anchor" href="#コマンド" aria-label="Permalink to &quot;コマンド&quot;">​</a></h2><h3 id="update" tabindex="-1">update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;update&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>設定を検証し、キャッシュとレスポンスをクリアし、すべての spec ファイルを再ダウンロードします。また、認証スクリプトの存在を確認し、孤立スクリプトを削除します。</p><p>このコマンドは以下を行った後に使用します：</p><ul><li>collection の追加または削除</li><li>collection の location の変更</li><li>再キャッシュが必要な spec ファイルの編集</li></ul><h3 id="clean" tabindex="-1">clean <a class="header-anchor" href="#clean" aria-label="Permalink to &quot;clean&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p><code>cache/</code> と <code>responses/</code> のすべての内容と、孤立した認証スクリプトを削除します。spec の再キャッシュは<strong>行いません</strong> — それには <code>update</code> を使用してください。</p><h3 id="validate" tabindex="-1">validate <a class="header-anchor" href="#validate" aria-label="Permalink to &quot;validate&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>すべての collection location を含む設定を検証します。<a href="./../cli/validate">CLI: validate</a> を参照してください。</p><h2 id="エクスポートとインポート" tabindex="-1">エクスポートとインポート <a class="header-anchor" href="#エクスポートとインポート" aria-label="Permalink to &quot;エクスポートとインポート&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ワークスペースを ZIP にエクスポート（デフォルト名：swag2mcp-backup-{date}.zip）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 特定のパスにエクスポート</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 特定の spec のみをエクスポート</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># バックアップから復元</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span></span></code></pre></div><p>エクスポートに含まれるもの：<code>swag2mcp.yaml</code>、<code>specs/</code>、<code>auth_scripts/</code>。キャッシュとレスポンスは除外されます（これらはローカルデータです）。</p><h2 id="gitignore" tabindex="-1">.gitignore <a class="header-anchor" href="#gitignore" aria-label="Permalink to &quot;.gitignore&quot;">​</a></h2><p>ワークスペースが Git リポジトリ内にある場合、以下のエントリを <code>.gitignore</code> に追加します：</p><div class="language-gitignore vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gitignore</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># swag2mcp — ローカルデータのみ</span></span>
<span class="line"><span>.swag2mcp/cache/</span></span>
<span class="line"><span>.swag2mcp/responses/</span></span></code></pre></div><p><code>cache/</code> と <code>responses/</code> ディレクトリには、コミットすべきでないローカルでマシン固有のデータが含まれています。その他（<code>swag2mcp.yaml</code>、<code>specs/</code>、<code>auth_scripts/</code>）は、設定をチーム全体で共有するためにリポジトリに含めるべきです。</p>`,66)])])}const g=s(n,[["render",p]]);export{k as __pageData,g as default};
